<body>
    <h1>Billiards Game</h1>
    <button id="reset">Reset / Rack</button>
    <p id="instructions">Click and drag back on the cue ball to aim and shoot.</p>
    <canvas id="table" width="800" height="600"></canvas>
    <script>
        window.sim = {
            W: 800,
            H: 600,
            R: 10,

            balls: [],

            reset(balls) {
                this.balls = balls.map(ball => ({
                    x: ball.x,
                    y: ball.y,
                    vx: ball.vx || 0,
                    vy: ball.vy || 0,
                    cue: Boolean(ball.cue),
                    potted: false
                }));
            },

            state() {
                return this.balls.map(ball => ({
                    x: ball.x,
                    y: ball.y,
                    vx: ball.vx,
                    vy: ball.vy,
                    potted: ball.potted,
                    cue: ball.cue
                }));
            },

            shoot(vx, vy) {
                const cb = this.balls.find(b => b.cue);
                if (cb && !cb.potted) {
                    cb.vx = vx;
                    cb.vy = vy;
                }
            },

            pause() {
                this.paused = true;
            },

            resume() {
                this.paused = false;
                if (!this.running) this.startAnimation();
            },

            step(dt) {
                const dampingFactorPerSecond = 0.98;
                const damping = Math.pow(dampingFactorPerSecond, dt);

                for (let ball of this.balls)
                    if (!ball.potted) {
                        ball.vx *= damping;
                        ball.vy *= damping;
                    }

                for (let ball of this.balls)
                    if (!ball.potted) {
                        ball.x += ball.vx * dt;
                        ball.y += ball.vy * dt;
                    }

                const R = this.R, W = this.W, H = this.H;

                for (let ball of this.balls)
                    if (!ball.potted) {
                        if (ball.x < R) { ball.x = R; ball.vx *= -0.95 }
                        else if (ball.x > W - R) { ball.x = W - R; ball.vx *= -0.95 }

                        if (ball.y < R) { ball.y = R; ball.vy *= -0.95 }
                        else if (ball.y > H - R) { ball.y = H - R; ball.vy *= -0.95 }
                    }

                for (let i=0; i<this.balls.length-1; i++) {
                    const b1 = this.balls[i];
                    if (!b1.potted)
                        for (let j=i+1; j<this.balls.length; j++) {
                            const b2 = this.balls[j];
                            if (!b2.potted) {
                                let dx = b2.x - b1.x, dy = b2.y - b1.y;
                                let distSq = dx*dx + dy*dy, minDist = 2 * R;

                                if (distSq < minDist*minDist && distSq > 0.01) {
                                    const d = Math.sqrt(distSq), nx = dx/d, ny = dy/d;
                                    const v1n = b1.vx*nx + b1.vy*ny, v2n = b2.vx*nx + b2.vy*ny;
                                    const delta = v2n - v1n;

                                    b1.vx += delta * nx;
                                    b1.vy += delta * ny;
                                    b2.vx -= delta * nx;
                                    b2.vy -= delta * ny;
                                }
                            }
                        }
                }

                const pockets = [
                    {x: R, y: R}, 
                    {x: W-R, y: R}, 
                    {x: W-R, y: H-R}, 
                    {x: R, y: H-R}, 
                    {x: R, y: H/2}, 
                    {x: W-R, y: H/2}
                ];

                for (let ball of this.balls)
                    if (!ball.potted) {
                        let potted = false;
                        for (let pocket of pockets) {
                            const dx = ball.x - pocket.x, dy = ball.y - pocket.y;
                            if (dx*dx + dy*dy < 900) { // 30px radius
                                ball.potted = true;
                                ball.vx = 0; ball.vy = 0;
                                potted = true;
                                break;
                            }
                        }
                    }

                this.redraw();
            },

            redraw() {
                const ctx = document.getElementById('table').getContext('2d');

                // Clear
                ctx.clearRect(0, 0, this.W, this.H);

                // Table
                ctx.fillStyle = '#3e8e41';
                ctx.fillRect(0, 0, this.W, this.H);

                // Rails
                ctx.strokeStyle = '#000';
                ctx.lineWidth = 2;
                ctx.strokeRect(this.R, this.R, this.W-2*this.R, this.H-2*this.R);

                // Pockets
                for (let p of [
                    {x: this.R, y: this.R}, 
                    {x: this.W-this.R, y: this.R}, 
                    {x: this.W-this.R, y: this.H-this.R}, 
                    {x: this.R, y: this.H-this.R}, 
                    {x: this.R, y: this.H/2}, 
                    {x: this.W-this.R, y: this.H/2}
                ]) {
                    ctx.beginPath();
                    ctx.arc(p.x, p.y, 10, 0, Math.PI*2);
                    ctx.fillStyle = '#000';
                    ctx.fill();
                }

                // Balls
                for (let ball of this.balls)
                    if (!ball.potted) {
                        ctx.beginPath();
                        ctx.arc(ball.x, ball.y, this.R, 0, Math.PI*2);
                        ctx.fillStyle = ball.cue ? '#fff' : '#000';
                        ctx.fill();
                        ctx.stroke();
                    }

                // Aim line
                const table = document.getElementById('table');
                if (isDragging && cueBall) {
                    let rect = table.getBoundingClientRect();
                    let dx = mouseX - dragStartX, dy = mouseY - dragStartY;
                    let len = Math.sqrt(dx*dx + dy*dy);

                    ctx.beginPath();
                    ctx.moveTo(dragStartX, dragStartY);
                    if (len > 0) {
                        const maxLen = 50, scale = Math.min(1, len / maxLen);
                        dx *= scale; dy *= scale;
                        ctx.lineTo(dragStartX + dx, dragStartY + dy);
                    } else {
                        ctx.lineTo(dragStartX, dragStartY);
                    }

                    ctx.strokeStyle = '#fff';
                    ctx.lineWidth = 2;
                    ctx.stroke();
                }
            },

            running: false,
            paused: false,

            startAnimation() {
                if (!this.running && !this.paused) {
                    this.running = true;
                    const lastTime = performance.now();
                    (function loop(time) {
                        const dt = (time - lastTime)/1000;
                        window.sim.step(dt);
                        lastTime = time;
                        if (window.sim.running && !window.sim.paused)
                            requestAnimationFrame(loop);
                    })(lastTime);
                }
            },
        };

        let isDragging = false, cueBall = null, dragStartX = 0, dragStartY = 0, mouseX = 0, mouseY = 0;

        const tableCanvas = document.getElementById('table');
        if (tableCanvas) {
            tableCanvas.addEventListener('mousedown', e => {
                const rect = tableCanvas.getBoundingClientRect();
                mouseX = e.clientX - rect.left;
                mouseY = e.clientY - rect.top;

                for (let ball of window.sim.balls)
                    if (!ball.potted && ball.cue) {
                        let dx = mouseX - ball.x, dy = mouseY - ball.y;
                        if (dx*dx + dy*dy < window.sim.R**2) {
                            isDragging = true;
                            cueBall = ball;
                            dragStartX = mouseX;
                            dragStartY = mouseY;
                            window.sim.pause();
                            window.sim.redraw();
                        }
                    }
            });

            tableCanvas.addEventListener('mousemove', e => {
                const rect = tableCanvas.getBoundingClientRect();
                mouseX = e.clientX - rect.left;
                mouseY = e.clientY - rect.top;

                if (isDragging && cueBall)
                    window.sim.redraw();
            });

            tableCanvas.addEventListener('mouseup', e => {
                if (isDragging && cueBall) {
                    isDragging = false;

                    const rect = tableCanvas.getBoundingClientRect();
                    mouseX = e.clientX - rect.left;
                    mouseY = e.clientY - rect.top;

                    let dx = mouseX - dragStartX, dy = mouseY - dragStartY;
                    let len = Math.sqrt(dx*dx + dy*dy);

                    if (len > 0) {
                        dx /= len; dy /= len;
                        const speed = Math.min(len, 50) * 20;
                        window.sim.shoot(-dx * speed, -dy * speed);
                    }

                    cueBall = null;
                    window.sim.resume();
                }
            });
        }

        document.getElementById('reset').addEventListener('click', () => {
            window.sim.reset([
                {x: 400, y: 300, cue: true},
                {x: 350, y: 280}, 
                {x: 450, y: 280}, 
                {x: 400, y: 260}
            ]);
        });

        window.addEventListener('load', () => {
            window.sim.reset([
                {x: 400, y: 300, cue: true},
                {x: 350, y: 280}, 
                {x: 450, y: 280}, 
                {x: 400, y: 260}
            ]);
            window.sim.resume();
        });
    </script>
</body>
