<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8" />
    <title>Billiards Game</title>
    <style>
        body {
            display: flex;
            justify-content: center;
            align-items: center;
            height: 100vh;
            margin: 0;
            background-color: #222;
            color: white;
            font-family: Arial, sans-serif;
        }
        canvas {
            border: 3px solid black;
            cursor: crosshair;
        }
        button {
            position: absolute;
            top: 20px;
            left: 50%;
            transform: translateX(-50%);
            padding: 10px 20px;
            font-size: 16px;
            z-index: 10;
        }
        #instructions {
            position: absolute;
            top: 80px;
            left: 50%;
            transform: translateX(-50%);
            background-color: rgba(0,0,0,0.7);
            padding: 10px 20px;
            border-radius: 8px;
            color: white;
            font-size: 14px;
        }
    </style>
</head>
<body>
    <div id="instructions">Click on cue ball, drag back to aim and shoot. Release to strike.</div>
    <button id="reset">Reset / Rack</button>
    <canvas id="table" width="800" height="600"></canvas>

    <script>
        window.onload = () => {
            const canvas = document.getElementById('table');
            const ctx = canvas.getContext('2d');

            let isDragging = false;
            let dragStartX, dragStartY;
            let cueBall;
            let currentMouseX, currentMouseY;

            window.sim = {
                W: 800,
                H: 600,
                R: 15,
                friction: 0.3,
                wallElasticity: 0.98,
                paused: false,

                balls: [],

                reset(balls) {
                    this.balls = balls.map(ball => ({
                        x: ball.x,
                        y: ball.y,
                        vx: ball.vx || 0,
                        vy: ball.vy || 0,
                        cue: !!ball.cue,
                        potted: false
                    }));
                    this.paused = false;
                },

                step(dt) {
                    for (let ball of this.balls) {
                        if (!ball.potted) {
                            ball.vx *= Math.exp(-this.friction * dt);
                            ball.vy *= Math.exp(-this.friction * dt);
                        }
                    }

                    // Handle wall collisions
                    for (let ball of this.balls) {
                        if (!ball.potted) {
                            let x = ball.x;
                            let y = ball.y;

                            if (x < this.R) {
                                ball.vx *= -this.wallElasticity;
                                x = this.R;
                            } else if (x > this.W - this.R) {
                                ball.vx *= -this.wallElasticity;
                                x = this.W - this.R;
                            }

                            if (y < this.R) {
                                ball.vy *= -this.wallElasticity;
                                y = this.R;
                            } else if (y > this.H - this.R) {
                                ball.vy *= -this.wallElasticity;
                                y = this.H - this.R;
                            }

                            ball.x = x;
                            ball.y = y;
                        }
                    }

                    // Check inter-ball collisions
                    const collisionPairs = [];
                    for (let i=0; i < this.balls.length; i++) {
                        for (let j=i+1; j < this.balls.length; j++) {
                            const b1 = this.balls[i];
                            const b2 = this.balls[j];
                            if (!b1.potted && !b2.potted) {
                                let dx = b2.x - b1.x;
                                let dy = b2.y - b1.y;
                                let distSq = dx*dx + dy*dy;
                                const minDist = 2 * this.R;
                                if (distSq < minDist * minDist) {
                                    collisionPairs.push([i, j]);
                                }
                            }
                        }
                    }

                    for (let [i,j] of collisionPairs) {
                        this.resolveBallCollision(this.balls[i], this.balls[j]);
                    }

                    // Update positions
                    for (let ball of this.balls) {
                        if (!ball.potted) {
                            ball.x += ball.vx * dt;
                            ball.y += ball.vy * dt;
                        }
                    }

                    // Check pockets
                    for (let ball of this.balls) {
                        if (!ball.potted && !this.isBallInPocket(ball)) continue;
                        if (!ball.potted) {
                            ball.potted = true;
                        }
                    }

                    this.redraw();
                },

                resolveBallCollision(b1, b2) {
                    const dx = b2.x - b1.x;
                    const dy = b2.y - b1.y;
                    let dist = Math.sqrt(dx*dx + dy*dy);
                    if (dist === 0) return;

                    const nx = dx / dist;
                    const ny = dy / dist;

                    const vrelDotN = (b1.vx - b2.vx)*nx + (b1.vy - b2.vy)*ny;

                    if (vrelDotN > 0) return; // balls are moving apart

                    const v1n = b1.vx * nx + b1.vy * ny;
                    const v2n = b2.vx * nx + b2.vy * ny;

                    b1.vx += (v2n - v1n) * nx;
                    b1.vy += (v2n - v1n) * ny;
                    b2.vx += (v1n - v2n) * nx;
                    b2.vy += (v1n - v2n) * ny;

                    const overlap = 2 * this.R - dist;
                    if (overlap > 0) {
                        b1.x -= nx * overlap / 2;
                        b1.y -= ny * overlap / 2;
                        b2.x += nx * overlap / 2;
                        b2.y += ny * overlap / 2;
                    }
                },

                isBallInPocket(ball) {
                    const pockets = [
                        {x: this.R, y: this.R},
                        {x: this.W - this.R, y: this.R},
                        {x: this.W/2, y: this.R},
                        {x: this.R, y: this.H - this.R},
                        {x: this.W - this.R, y: this.H - this.R},
                        {x: this.W/2, y: this.H - this.R}
                    ];

                    for (let pocket of pockets) {
                        const dx = ball.x - pocket.x;
                        const dy = ball.y - pocket.y;
                        if (dx*dx + dy*dy < 150 * 150) return true;
                    }
                    return false;
                },

                redraw() {
                    ctx.clearRect(0, 0, this.W, this.H);

                    // Felt
                    ctx.fillStyle = '#2e8b57';
                    ctx.fillRect(0, 0, this.W, this.H);

                    // Rails
                    ctx.strokeStyle = 'saddlebrown';
                    ctx.lineWidth = 10;
                    ctx.strokeRect(this.R, this.R, this.W - 2 * this.R, this.H - 2 * this.R);

                    // Pockets
                    const pockets = [
                        {x: this.R, y: this.R},
                        {x: this.W - this.R, y: this.R},
                        {x: this.W/2, y: this.R},
                        {x: this.R, y: this.H - this.R},
                        {x: this.W - this.R, y: this.H - this.R},
                        {x: this.W/2, y: this.H - this.R}
                    ];

                    for (let pocket of pockets) {
                        ctx.beginPath();
                        ctx.arc(pocket.x, pocket.y, 10, 0, Math.PI*2);
                        ctx.fillStyle = 'black';
                        ctx.fill();
                    }

                    // Balls
                    for (let ball of this.balls) {
                        if (!ball.potted) {
                            ctx.beginPath();
                            ctx.arc(ball.x, ball.y, this.R, 0, Math.PI*2);
                            if (ball.cue) {
                                ctx.fillStyle = 'white';
                                ctx.fill();
                                // Cue ball dot
                                ctx.beginPath();
                                ctx.arc(ball.x + 10, ball.y - 5, 4, 0, Math.PI*2);
                                ctx.fillStyle = 'black';
                                ctx.fill();
                            } else {
                                ctx.fillStyle = 'red';
                                ctx.fill();
                            }
                        }
                    }

                    // Aim line
                    if (isDragging) {
                        ctx.beginPath();
                        ctx.moveTo(currentMouseX, currentMouseY);
                        ctx.lineTo(cueBall.x, cueBall.y);
                        ctx.strokeStyle = 'white';
                        ctx.lineWidth = 2;
                        ctx.setLineDash([5, 5]);
                        ctx.stroke();
                        ctx.setLineDash([]);
                    }
                },

                state() {
                    return this.balls.map(ball => ({
                        x: ball.x,
                        y: ball.y,
                        vx: ball.vx,
                        vy: ball.vy,
                        potted: ball.potted,
                        cue: ball.cue
                    }));
                },

                shoot(vx, vy) {
                    for (let ball of this.balls) {
                        if (ball.cue && !ball.potted) {
                            ball.vx = vx;
                            ball.vy = vy;
                            break;
                        }
                    }
                },

                pause() {
                    this.paused = true;
                },
                resume() {
                    this.paused = false;
                },
            };

            // Animation loop
            let lastTime = performance.now();
            function animate(time) {
                const dt = (time - lastTime) / 1000; // seconds
                if (!sim.paused) {
                    sim.step(dt);
                }
                lastTime = time;
                requestAnimationFrame(animate);
            }

            requestAnimationFrame(animate);

            // Mouse event handlers
            canvas.addEventListener('mousedown', e => {
                const rect = canvas.getBoundingClientRect();
                const mx = e.clientX - rect.left;
                const my = e.clientY - rect.top;

                for (let ball of sim.balls) {
                    if (!ball.potted && ball.cue) {
                        const dx = mx - ball.x;
                        const dy = my - ball.y;
                        if (dx*dx + dy*dy <= sim.R * sim.R) {
                            isDragging = true;
                            dragStartX = mx;
                            dragStartY = my;
                            cueBall = ball;
                            currentMouseX = mx;
                            currentMouseY = my;
                            e.preventDefault();
                        }
                    }
                }
            });

            canvas.addEventListener('mousemove', e => {
                if (!isDragging) return;

                const rect = canvas.getBoundingClientRect();
                currentMouseX = e.clientX - rect.left;
                currentMouseY = e.clientY - rect.top;
            });

            canvas.addEventListener('mouseup', () => {
                if (!isDragging) return;

                isDragging = false;

                // Calculate shot
                const dx = currentMouseX - dragStartX;
                const dy = currentMouseY - dragStartY;
                const distance = Math.sqrt(dx*dx + dy*dy);

                if (distance > 0) {
                    const maxDragDistance = 100; // pixels
                    const power = Math.min(distance, maxDragDistance) / maxDragDistance;

                    const directionX = dx / distance;
                    const directionY = dy / distance;

                    const shotSpeedMultiplier = 500;

                    const vx = -power * shotSpeedMultiplier * directionX;
                    const vy = -power * shotSpeedMultiplier * directionY;

                    sim.shoot(vx, vy);
                }
            });

            canvas.addEventListener('mouseleave', () => {
                isDragging = false;
            });

            // Reset button
            document.getElementById('reset').addEventListener('click', () => {
                function createRack() {
                    let balls = [];

                    // Cue ball
                    balls.push({
                        x: sim.W / 2,
                        y: sim.H - 3 * sim.R,
                        cue: true
                    });

                    // Other balls in a triangle formation
                    for (let i=0; i < 5; i++) {
                        const row = i;
                        const numBallsInRow = 5 - row;

                        for (let j=0; j < numBallsInRow; j++) {
                            let x = sim.W / 2 + (j - (numBallsInRow-1)/2) * 2 * sim.R;
                            let y = sim.H / 4 + row * 2 * sim.R;

                            balls.push({
                                x: x,
                                y: y,
                                cue: false
                            });
                        }
                    }

                    return balls;
                }

                const rackBalls = createRack();
                sim.reset(rackBalls);
            });

            // Initial setup
            document.getElementById('reset').click();
        };
    </script>
</body>
</html>
